"use client";

import { create } from "zustand";
import { useEffect, useMemo } from "react";
import type { FeatureCollection, Geometry } from "geojson";
import type { AreaRecord, BuildingWindow, CityDataset, CityId, FloodEvent, HourlyRainEvent, RainSeries, RainStation, SourceRef, WaterLevelStation } from "@/lib/types";
import { useDashboard } from "@/store/dashboard-store";

/**
 * Bundled datasets live in /public/data (generated by scripts/data/build-datasets.ts),
 * so the dashboard works offline once loaded — only basemap tiles need the network.
 */
export const DATA_BASE = "/data";

export interface AreaFeatureProps {
  fid: number;
  id: string;
  nameTh: string;
  nameEn: string;
  geometryStatus: string;
}

export interface CityBundle {
  dataset: CityDataset;
  areasGeo: FeatureCollection<Geometry, AreaFeatureProps>;
  waterways: FeatureCollection | null;
  drainage: FeatureCollection | null;
  stations: RainStation[] | null;
  rainGrid: RainSeries | null;
  rainAreas: RainSeries | null;
  floodEvents: FloodEvent[] | null;
  /** Hat Yai only */
  municipality: FeatureCollection | null;
  communities: FeatureCollection | null;
  /** Water-level gauge snapshot (public/data/<city>/water-levels.json). */
  waterLevels: WaterLevelStation[] | null;
  /** Hourly rainfall for documented events (public/data/<city>/rain-hourly.json). */
  rainHourly: HourlyRainEvent[] | null;
  /** Optional files that failed to load (shown in the Data drawer, never silently ignored). */
  missing: string[];
}

type LoadState<T> = { status: "idle" | "loading" | "ready" | "error"; data?: T; error?: string; /** epoch ms of the last failure */ failedAt?: number };

/**
 * Hooks re-request a failed city automatically only after this cool-down, so panels that mount
 * while a file is missing do not each re-fetch it (explicit Retry buttons call loadCity() directly).
 */
const AUTO_RETRY_MS = 15_000;
const autoLoadAllowed = (st: LoadState<unknown> | undefined) => !(st?.status === "error" && st.failedAt !== undefined && Date.now() - st.failedAt < AUTO_RETRY_MS);

async function getJson<T>(path: string): Promise<T> {
  const res = await fetch(`${DATA_BASE}/${path}`, { cache: "force-cache" });
  if (!res.ok) throw new Error(`${path}: HTTP ${res.status}`);
  return (await res.json()) as T;
}

async function optional<T>(path: string, missing: string[]): Promise<T | null> {
  try {
    return await getJson<T>(path);
  } catch {
    missing.push(path);
    return null;
  }
}

function assertDataset(d: unknown, city: CityId): asserts d is CityDataset {
  const ds = d as CityDataset;
  if (!ds || typeof ds !== "object" || !ds.city || !Array.isArray(ds.areas)) throw new Error(`${city}/areas.json: malformed dataset`);
  for (const a of ds.areas) {
    if (!a.id || !a.metrics) throw new Error(`${city}/areas.json: area missing id/metrics`);
  }
}

export async function loadCityBundle(city: CityId): Promise<CityBundle> {
  const missing: string[] = [];
  const [dataset, areasGeo] = await Promise.all([
    getJson<unknown>(`${city}/areas.json`),
    getJson<FeatureCollection<Geometry, AreaFeatureProps>>(`${city}/areas.geojson`),
  ]);
  assertDataset(dataset, city);
  const [waterways, drainage, stations, rainGrid, rainAreas, floodEvents, municipality, communities, waterLevels, rainHourly] = await Promise.all([
    optional<FeatureCollection>(`${city}/waterways.geojson`, missing),
    optional<FeatureCollection>(`${city}/drainage.geojson`, missing),
    optional<RainStation[]>(`${city}/stations.json`, missing),
    optional<RainSeries>(`${city}/rain-grid.json`, missing),
    optional<RainSeries>(`${city}/rain-areas.json`, missing),
    optional<FloodEvent[]>(`${city}/flood-events.json`, missing),
    city === "hatyai" ? optional<FeatureCollection>(`hatyai/municipality.geojson`, missing) : Promise.resolve(null),
    city === "hatyai" ? optional<FeatureCollection>(`hatyai/communities.geojson`, missing) : Promise.resolve(null),
    optional<WaterLevelStation[]>(`${city}/water-levels.json`, missing),
    optional<HourlyRainEvent[]>(`${city}/rain-hourly.json`, missing),
  ]);
  return { dataset, areasGeo, waterways, drainage, stations, rainGrid, rainAreas, floodEvents, municipality, communities, waterLevels, rainHourly, missing };
}

interface DataStore {
  cities: Partial<Record<CityId, LoadState<CityBundle>>>;
  sources: LoadState<SourceRef[]>;
  buildings: Record<string, LoadState<BuildingWindow>>;
  loadCity: (c: CityId) => Promise<void>;
  loadSources: () => Promise<void>;
  loadBuildings: (areaId: string) => Promise<void>;
}

export const useDataStore = create<DataStore>()((set, get) => ({
  cities: {},
  sources: { status: "idle" },
  buildings: {},
  loadCity: async (c) => {
    const cur = get().cities[c];
    if (cur && (cur.status === "loading" || cur.status === "ready")) return;
    set((s) => ({ cities: { ...s.cities, [c]: { status: "loading" } } }));
    try {
      const data = await loadCityBundle(c);
      set((s) => ({ cities: { ...s.cities, [c]: { status: "ready", data } } }));
    } catch (e) {
      set((s) => ({ cities: { ...s.cities, [c]: { status: "error", error: (e as Error).message, failedAt: Date.now() } } }));
    }
  },
  loadSources: async () => {
    if (get().sources.status !== "idle") return;
    set({ sources: { status: "loading" } });
    try {
      set({ sources: { status: "ready", data: await getJson<SourceRef[]>("sources.json") } });
    } catch (e) {
      set({ sources: { status: "error", error: (e as Error).message } });
    }
  },
  loadBuildings: async (areaId) => {
    const cur = get().buildings[areaId];
    if (cur && cur.status !== "idle" && cur.status !== "error") return;
    set((s) => ({ buildings: { ...s.buildings, [areaId]: { status: "loading" } } }));
    try {
      const data = await getJson<BuildingWindow>(`buildings/${areaId}.json`);
      set((s) => ({ buildings: { ...s.buildings, [areaId]: { status: "ready", data } } }));
    } catch (e) {
      set((s) => ({ buildings: { ...s.buildings, [areaId]: { status: "error", error: (e as Error).message } } }));
    }
  },
}));

/** Current city's bundle (triggers loading). Also pre-fetches the other city in the background. */
export function useCityBundle() {
  const cityId = useDashboard((s) => s.cityId);
  const state = useDataStore((s) => s.cities[cityId]);
  const loadCity = useDataStore((s) => s.loadCity);
  useEffect(() => {
    if (autoLoadAllowed(useDataStore.getState().cities[cityId])) void loadCity(cityId);
    const other: CityId = cityId === "bangkok" ? "hatyai" : "bangkok";
    const t = window.setTimeout(() => {
      if (autoLoadAllowed(useDataStore.getState().cities[other])) void loadCity(other);
    }, 2500);
    return () => window.clearTimeout(t);
  }, [cityId, loadCity]);
  return { cityId, status: state?.status ?? "loading", bundle: state?.data, error: state?.error };
}

/** Area lookup for the current city. */
export function useAreas() {
  const { bundle } = useCityBundle();
  return useMemo(() => {
    const list: AreaRecord[] = bundle?.dataset.areas ?? [];
    const byId = new Map(list.map((a) => [a.id, a] as const));
    const byFid = new Map(list.map((a) => [a.fid, a] as const));
    return { list, byId, byFid };
  }, [bundle]);
}

export function useSelectedArea() {
  const id = useDashboard((s) => s.selectedAreaId);
  const { byId } = useAreas();
  return id ? (byId.get(id) ?? null) : null;
}

export function useSources() {
  const state = useDataStore((s) => s.sources);
  const load = useDataStore((s) => s.loadSources);
  useEffect(() => {
    void load();
  }, [load]);
  return state;
}

export function useBuildingWindow(areaId: string | null) {
  const state = useDataStore((s) => (areaId ? s.buildings[areaId] : undefined));
  const load = useDataStore((s) => s.loadBuildings);
  useEffect(() => {
    if (areaId) void load(areaId);
  }, [areaId, load]);
  return areaId ? (state ?? { status: "loading" as const }) : { status: "idle" as const };
}
